void Rays::readDiagnostics(){auto& s=*state_;if(!s.diagnosticCopy)return;void* data=nullptr;D3D12_RANGE range{0,size_t(s.diagnosticCopy->GetDesc().Width)};check(s.diagnosticCopy->Map(0,&range,&data),"Read spectral caustic diagnostic");std::array<double,3> flux{},peak{},centroidX{},centroidY{};uint64_t lit=0,invalid=0;for(unsigned y=0;y<causticSize;++y){auto* row=reinterpret_cast<const DirectX::PackedVector::HALF*>(static_cast<const unsigned char*>(data)+s.diagnosticFootprint.Offset+y*s.diagnosticFootprint.Footprint.RowPitch);for(unsigned x=0;x<causticSize;++x){double value=0;for(int c=0;c<3;++c){const auto v=double(DirectX::PackedVector::XMConvertHalfToFloat(row[x*4+c]));if(!std::isfinite(v)||v<0){++invalid;continue;}flux[c]+=v;peak[c]=std::max(peak[c],v);centroidX[c]+=v*x;centroidY[c]+=v*y;value+=v;}if(value>1e-6)++lit;}}D3D12_RANGE empty{};s.diagnosticCopy->Unmap(0,&empty);for(int c=0;c<3;++c)if(flux[c]>0){centroidX[c]/=flux[c];centroidY[c]/=flux[c];}s.diagnostics={{"litTexels",lit},{"invalidValues",invalid},{"fluxSumRgb",flux},{"peakRgb",peak},{"centroidTexelX",centroidX},{"centroidTexelY",centroidY},{"readbackOnlyDuringCapture",true}};s.diagnosticCopy.Reset();}
